python3 - <<'PY'
p='src/service.ts'
s=open(p).read().replace("    if (!document) throw new Error('not found');", "    if (!document || document.deleted || document.tenant !== actor.tenant) {\n      throw new Error('not found');\n    }\n    if (actor.role !== 'admin' && !(actor.role === 'editor' && document.owner === actor.user)) {\n      throw new Error('forbidden');\n    }")
open(p,'w').write(s)
PY
cat >> checks/public.cjs <<'EOF'

// Visibility and permissions apply even when archiving would otherwise be a no-op.
for (const role of ['admin', 'editor', 'viewer']) {
  for (const archived of [false, true]) {
    for (const kind of ['missing', 'deleted', 'foreign', 'owned', 'other']) {
      const documents = [
        { id: 'target', tenant: kind === 'foreign' ? 'b' : 'a', owner: kind === 'other' ? 'other' : 'u', deleted: kind === 'deleted', archived },
        { id: 'untouched', tenant: 'a', owner: 'u', deleted: false, archived: false },
      ];
      const repository = new DocumentRepository(documents);
      repository.audit.push({ actor: 'prior', document: 'prior' });
      const before = JSON.parse(JSON.stringify({ documents, audit: repository.audit }));
      const documentService = new DocumentService(repository);
      const actor = { tenant: 'a', user: 'u', role };
      const id = kind === 'missing' ? 'absent' : 'target';
      const invisible = ['missing', 'deleted', 'foreign'].includes(kind);
      const forbidden = role === 'viewer' || (role === 'editor' && kind === 'other');
      if (invisible || forbidden) {
        assert.throws(() => documentService.archive(actor, id), { message: invisible ? 'not found' : 'forbidden' });
        assert.deepEqual({ documents, audit: repository.audit }, before);
      } else {
        documentService.archive(actor, id);
        before.documents[0].archived = true;
        if (!archived) before.audit.push({ actor: 'u', document: id });
        assert.deepEqual({ documents, audit: repository.audit }, before);
        documentService.archive(actor, id);
        assert.deepEqual({ documents, audit: repository.audit }, before);
      }
    }
  }
}
EOF
tsc -p tsconfig.json && node checks/public.cjs

